const llm = $json; let p = { patterns: [], anti_patterns: [] };
try { const c = llm.choices && llm.choices[0] && llm.choices[0].message && llm.choices[0].message.content; if (c) p = JSON.parse(c); } catch(e){ p = { patterns: [], anti_patterns: [] }; }
const now = new Date().toISOString();
const rows = [];
for (const x of (p.patterns || [])) {
  if ((x.sample_size || 0) < 10) continue;
  rows.push({ json: {
    id: 'pat_' + Date.now() + '_' + Math.random().toString(36).slice(2,6),
    ts: now,
    pattern_type: x.pattern_type || 'winning_action',
    niche: x.niche || 'all',
    trigger_signal: x.trigger_signal || '',
    winning_action: x.winning_action || '',
    sample_size: x.sample_size,
    success_rate: x.success_rate || '',
    confidence: x.confidence || 'low',
    note: x.note || ''
  }});
}
for (const x of (p.anti_patterns || [])) {
  if ((x.sample_size || 0) < 10) continue;
  rows.push({ json: {
    id: 'anti_' + Date.now() + '_' + Math.random().toString(36).slice(2,6),
    ts: now,
    pattern_type: 'losing_action',
    niche: 'all',
    trigger_signal: x.trigger_signal || '',
    winning_action: 'AVOID:' + (x.losing_action || ''),
    sample_size: x.sample_size,
    success_rate: 1 - (x.fail_rate || 0),
    confidence: 'medium',
    note: x.note || ''
  }});
}
if (rows.length === 0) { rows.push({ json: { id:'pat_none_'+Date.now(), ts:now, pattern_type:'insufficient_data', niche:'all', trigger_signal:'', winning_action:'', sample_size:0, success_rate:'', confidence:'low', note:'pas assez de données pour extraire un pattern fiable' }}); }
return rows;
